CREATE TABLE IF NOT EXISTS personnel_profiles (
 id INT AUTO_INCREMENT PRIMARY KEY, school_id INT NOT NULL, user_id INT NULL, personnel_number VARCHAR(40) NOT NULL,
 first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,first_name_ar VARCHAR(100) NULL,last_name_ar VARCHAR(100) NULL,cin VARCHAR(80) NULL,date_of_birth DATE NULL,birth_place VARCHAR(150) NULL,gender VARCHAR(20) NULL,nationality VARCHAR(100) NULL,address VARCHAR(255) NULL,city VARCHAR(100) NULL,phone VARCHAR(30) NULL,email VARCHAR(150) NULL,emergency_contact_name VARCHAR(180) NULL,emergency_contact_phone VARCHAR(30) NULL,
 personnel_type ENUM('TEACHER','ADMINISTRATIVE_STAFF') NOT NULL,job_title VARCHAR(150) NULL,job_function VARCHAR(150) NULL,service_assignment VARCHAR(150) NULL,entry_date DATE NULL,contract_type ENUM('CDI','CDD','VACATAIRE','STAGE','AUTRE') NULL,status ENUM('ACTIF','EN_CONGE','ARCHIVE') NOT NULL DEFAULT 'ACTIF',main_degree VARCHAR(180) NULL,specialty VARCHAR(180) NULL,work_time ENUM('TEMPS_PLEIN','TEMPS_PARTIEL') NULL,administrative_department VARCHAR(150) NULL,primary_mission TEXT NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY personnel_school_number_unique(school_id,personnel_number),UNIQUE KEY personnel_school_cin_unique(school_id,cin),UNIQUE KEY personnel_user_unique(user_id),KEY personnel_school_type_status(school_id,personnel_type,status),CONSTRAINT personnel_school_fk FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,CONSTRAINT personnel_user_fk FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
);
